function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
const btn=(text,action,cls='',attrs='')=>{if(readOnly()&&['revision','preview','apply','undo','import','submit-import','retry','retry-visual','tags','new-chat','send','new-kb','members','note-create'].includes(action)&&!attrs.includes('disabled'))attrs+=' disabled title="只读账号不能执行此操作"';return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;};
function diagram(type='agent'){
 const labels=type==='postgres'?['连接请求','连接池','数据库']:type==='design'?['层级','排版','阅读']:['业务知识','Skills / Tools','Agent'];
 return `<svg viewBox="0 0 460 210" role="img" aria-label="${labels.join('、')}的本地示意图"><g fill="none" stroke="var(--line)" stroke-width="1.5"><path d="M155 52H222V103M155 158H222V103M320 103H368"/></g><g fill="var(--input)" stroke="var(--line)"><rect x="18" y="29" width="137" height="46" rx="6"/><rect x="18" y="135" width="137" height="46" rx="6"/><rect x="222" y="75" width="98" height="56" rx="6"/><rect x="368" y="80" width="75" height="46" rx="6"/></g><g fill="var(--sub)" font-size="14" text-anchor="middle" font-family="system-ui, PingFang SC"><text x="86" y="57">${labels[0]}</text><text x="86" y="164">用户问题</text><text x="271" y="108">${labels[1]}</text><text x="405" y="108">${labels[2]}</text></g><path d="M271 131v57H86v-7" stroke="var(--accent)" stroke-width="1.5" fill="none"/><text x="169" y="181" fill="var(--accent)" font-size="11" font-family="system-ui">反馈与核查</text></svg>`;
}
const agentChapters=[
 {id:'pain',title:'为什么传统配置越来越难维护',time:72,body:'传统客服系统将意图、话术、提示词和流程拆成多个配置模块。运营人员要在不同界面之间切换，既要记住配置关系，也要处理业务不断出现的变化。',extra:'问题不只是配置数量多，而是业务知识散落在不同视角中。新同事接手时，需要先理解系统的配置方式，才能调整一个具体场景。'},
 {id:'skills',title:'用 Skills 和 Tools 组织业务知识',time:285,body:'将业务场景收拢为可理解的技能说明，再由工具提供执行能力。Skills 解释什么时候做、如何判断；Tools 负责查询和具体操作。',extra:'这种组织方式把配置态的复杂度前移到知识的表达中。它并不意味着可以省略权限、工具边界或失败恢复，而是让维护者更容易理解一个完整场景。',figure:true},
 {id:'case',title:'一个例子：先问清楚用户的直播间',time:472,body:'遇到“直播间有问题”这样的请求，系统首先需要获得足够信息。把追问用户 ID、确认直播间和查询状态组织在同一个技能中，可以避免为每一种话术再写一条流程。',extra:'关键是保留判断所依赖的前提。不能把“自主处理”理解为不需要用户确认，也不能把一个场景的成功推及全部长尾问题。'},
 {id:'loop',title:'让反馈进入下一次改进',time:691,body:'满意度、错误案例、人工标注和评测需要形成持续回路。错误记录只有经过归因和验证，才能进入下一版技能或示例库。',extra:'视频提出了反馈机制，但并未给出所有环节的量化效果。核查时应关注具体数据如何回流、由谁确认，以及更新后如何评测。'}
];
const videos=[
 {id:'agent',title:'从传统客服到 Agent：如何组织业务知识',description:'从配置负担到 Skills 与 Tools，再到可持续改进的反馈回路。用具体案例理解架构变化。',tags:['Agent','软件架构'],duration:'15:04',source:'B 站',status:'ready',type:'agent'},
 {id:'postgres',title:'PostgreSQL 连接池：从参数到实际边界',description:'连接池解决什么问题，哪些参数需要结合工作负载核查，以及常见的配置误区。',tags:['数据库','性能'],duration:'28:16',source:'本地文件',status:'ready',type:'postgres'},
 {id:'design',title:'为阅读而设计：层级、节奏与留白',description:'如何让用户看见内容、辨认操作，并在连续阅读中保持清晰的空间关系。',tags:['设计','阅读体验'],duration:'21:09',source:'B 站',status:'partial',type:'design'},
 {id:'queue',title:'消息队列的重复投递与幂等处理',description:'摘要正在整理中。已保存视频，任务将在后台继续。',tags:['后端'],duration:'32:50',source:'B 站',status:'processing',type:'agent'},
 {id:'missing',title:'WEB_ae290462-6654-4d30-ac5b-ce84855ab319_一份没有封面的长文件名示例.mp4',description:'没有封面也可以通过标题与摘要找到内容。原文件名只展示一次。',tags:['系统设计'],duration:'18:22',source:'本地文件',status:'ready',type:'none'},
 {id:'failed',title:'如何核查一条不确定的结论',description:'视频已保存，摘要暂未生成。可以保留已有内容并只重试摘要。',tags:['方法'],duration:'12:04',source:'B 站',status:'failed',type:'none'}
];
const baseState={theme:'dark',scenario:'normal',version:1,edited:false,undoAvailable:false,read:{},mediaTimes:{},drafts:{},refs:{},messages:{},time:0,playing:false,pane:'playback',side:innerWidth>1100,view:'summary',tagNames:['Agent','软件架构','知识组织','反馈闭环','客服'],generation:'waiting',importTitle:'',events:[{title:'整理章节内容',state:'done',duration:'18 秒'},{title:'查看相关画面',state:'running',duration:'进行中'}],revision:null,importDraft:{tab:'url',url:'',focus:'',visual:true,tags:true,auto:true,policy:'优先平台字幕，不可用时转写',language:'自动选择',form:'自动选择'},noteView:'text',scope:'library',currentSession:'new'};
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
let state={...structuredClone(baseState),...saved,playing:false};
function syncImported(){if(!state.importTitle)return;const item={id:'imported',title:state.importTitle,description:'本地导入演示：完成后展示布局用摘要，不解析所填链接或文件。',tags:[],duration:'演示',source:state.importDraft.tab==='url'?'B 站':'本地文件',status:state.scenario==='imported'?'imported':state.generation==='complete'?'ready':state.generation==='text_ready'?'partial':'processing',type:'none'};const i=videos.findIndex(v=>v.id==='imported');if(i<0)videos.unshift(item);else videos[i]=item;}
syncImported();
let currentID=null,currentRoute='library',toastTimer,answerTimer,activeQuestionKey=null,selectedQuote=null,lastFocus=null,dialogKind='';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function readOnly(){return state.scenario==='readonly';}
function legacy(){return state.scenario==='legacy';}
function dataVideo(){return videos.find(x=>x.id===currentID)||videos[0];}
function getChapters(){if(currentID==='agent')return agentChapters.map((c,i)=>({...c,body:state.edited&&i===0?'传统客服系统的维护难点是业务知识分散：同一个场景要在意图、话术和流程等配置之间来回切换。新人需要先理解这些关系，才能做出可靠调整。':c.body}));const v=dataVideo();return [{id:'intro',title:'问题与使用场景',time:45,body:v.description,extra:'这是为布局评审编写的示例正文，不是对真实视频的自动总结。'},{id:'method',title:'方法与适用条件',time:300,body:`理解「${v.title}」需要把步骤、判断依据和适用条件一起保留下来。只看一个参数或一个工具，并不能判断它是否适合当前场景。`,extra:'保留可以回查的来源位置，让读者能够核查关键假设。',figure:v.type!=='none'},{id:'limits',title:'如何回查与继续提问',time:600,body:'先找到需要核实的段落，再检查对应来源。对不确定内容可以发起普通提问，需要改变正文时另行预览修订。',extra:'本页的数据、画面和问答均为本地模拟。'}];}
function summaryText(){return currentID==='agent'?'视频讨论了如何把分散的客服配置，整理成可理解的业务技能。重点不是增加一个 Agent，而是降低知识维护成本，并让案例、反馈和评测形成持续改进的回路。':dataVideo().description;}
function route(){return new URL(location.hash.slice(1)||'/library','https://prototype.local');}
function routeTo(path){captureRead();location.hash=path;}
function currentVersion(){return currentID==='agent'?state.version:1;}
function videoScenario(){return state.scenario==='normal'?({processing:'processing',partial:'partial',failed:'failed'}[dataVideo().status]||'normal'):state.scenario;}
function captureRead(){const el=$('.document');if(el&&currentRoute==='video'){state.read[currentID]={top:el.scrollTop,version:Number(el.dataset.version)};state.mediaTimes[currentID]=state.time;}save();}
function stateDisplay(v){let s=v.status;if(v.id===(currentID||'agent')){s=['processing','partial','failed'].includes(state.scenario)?state.scenario:s;}
 return s==='imported'?'<span class="state">已导入 · 待生成摘要</span>':s==='ready'?`<span class="state good">${icon('check')}摘要可读</span>`:s==='partial'?'<span class="state working"><span class="status-dot"></span><span>摘要可读<small>配图未完成</small></span></span>':s==='failed'?`<span class="state bad">${icon('alert')}摘要未生成</span>`:'<span class="state working running"><span class="status-dot"></span><span>正在整理内容<small>可离开，后台继续</small></span></span>';}
function scenarioControl(){const options=[['normal','默认完整内容'],['processing','等待与处理中'],['partial','文字可读 / 补图失败'],['failed','摘要失败'],['no_config','缺少配置'],['offline','连接中断'],['source_error','来源不可用'],['legacy','历史摘要'],['readonly','只读账号'],['empty','空视频库'],['long','长内容 / 多标签'],['multiple_errors','多个局部错误']];return `<div class="scenario"><span>原型场景</span><select aria-label="选择模拟场景">${options.map(([x,n])=>`<option value="${x}" ${state.scenario===x?'selected':''}>${n}</option>`).join('')}</select><span>手动切换，不请求真实服务</span>${state.scenario==='processing'?btn('下一模拟事件','advance','small ghost'):''}</div>`;}
function renderShell(){document.documentElement.dataset.theme=state.theme;$('#theme-label').textContent=state.theme==='dark'?'浅色外观':'深色外观';$('#nav').innerHTML=[['library','视频库','library'],['chat','问答','ask'],['kb','知识库','folder']].map(([p,n,i])=>`<a class="nav-link ${(p===currentRoute||p==='library'&&currentRoute==='video')?'active':''}" href="#/${p}" title="${n}" ${p===currentRoute?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${n}</span></a>`).join('');$('#active-count').textContent=state.generation==='complete'?'0':'1';hydrateIcons();}
function render(){captureRead();const u=route(),p=u.pathname.split('/').filter(Boolean);currentRoute=p[0]==='v'?'video':p[0]||'library';if(currentRoute==='video'){const nextID=p[1]||'agent';if(nextID!==currentID){currentID=nextID;state.time=state.mediaTimes[currentID]||0;state.playing=false;}}if(currentRoute==='library')state.libraryURL=u.pathname+u.search;renderShell();$('#crumb').innerHTML=currentRoute==='video'?`<a href="#${escapeHTML(state.libraryURL||'/library')}">视频库</a><span>/</span><span>摘要</span>`:`<span>${({library:'视频库',chat:'问答',kb:'知识库',notes:'学习笔记'}[currentRoute]||'视频库')}</span>`;
 $('#main').innerHTML=currentRoute==='video'?readerHTML():currentRoute==='chat'?chatHTML():currentRoute==='kb'?kbHTML(p[1]):currentRoute==='notes'?notesHTML(p[1]):libraryHTML(u);hydrateIcons($('#main'));attachInputs();if(currentRoute==='video'){const el=$('.document');const r=state.read[currentID];if(r&&r.version===currentVersion())el.scrollTop=r.top;el.addEventListener('scroll',()=>{state.read[currentID]={top:el.scrollTop,version:Number(el.dataset.version)};save();},{passive:true});renderAssistant();}save();}
function libraryHTML(u){const q=u.searchParams.get('q')||'',status=u.searchParams.get('status')||'all',tag=u.searchParams.get('tag')||'',grid=u.searchParams.get('view')==='grid';let list=state.scenario==='empty'?[]:videos.filter(v=>(v.title+v.description+v.tags.join(' ')).toLowerCase().includes(q.toLowerCase())&&(!tag||v.tags.includes(tag))&&(status==='all'||status==='ready'&&['ready','partial'].includes(v.status)||v.status===status));
 return `<div class="page"><div class="page-head"><div><h1>视频库</h1><p>把视频留下来，把重要的内容读进去。</p></div>${btn(icon('plus')+'导入视频','import','primary',readOnly()?'disabled title="只读账号不能导入"':'')}</div>${state.scenario!=='empty'&&!q&&!tag&&status==='all'?`<section class="resume" aria-label="继续阅读"><div class="resume-art">${diagram()}</div><div class="resume-copy"><span class="eyebrow">继续阅读</span><h2>${escapeHTML(videos[0].title)}</h2><p>${state.read.agent?'上次阅读的位置已保存在本机 · 当前版本 v'+state.version:'先理解核心结论，再回到原片核查 · 15:04'}</p></div><a class="btn" href="#/v/agent">继续阅读 ${icon('arrow')}</a></section>`:''}<div class="toolbar"><div class="search">${icon('search')}<input aria-label="搜索视频" placeholder="搜索标题、摘要或标签" value="${escapeHTML(q)}"></div><div class="seg" aria-label="视频状态">${[['all','全部'],['ready','可阅读'],['processing','处理中'],['failed','未完成']].map(([v,n])=>`<button data-action="filter" data-status="${v}" aria-pressed="${status===v}">${n}</button>`).join('')}</div></div><div class="filterline"><span class="small">标签</span>${['Agent','数据库','设计'].map(t=>`<button class="tag-button" data-action="filter-tag" data-tag="${t}" aria-pressed="${tag===t}">${t}</button>`).join('')}${btn('全部标签','filter-tags','small ghost')}<div class="seg view-toggle" aria-label="显示方式"><button data-action="list-view" data-view="list" aria-pressed="${!grid}">列表</button><button data-action="list-view" data-view="grid" aria-pressed="${grid}">卡片</button></div></div><div class="section-title"><h2>${q||tag||status!=='all'?'筛选结果':'所有视频'} <span class="small">${list.length}</span></h2><span class="small">最近更新</span></div>${list.length?`<div class="collection ${grid?'library-grid':''}">${list.map(v=>`<article class="video-row"><a class="thumb" href="#/v/${v.id}" aria-label="打开 ${escapeHTML(v.title)}">${v.type==='none'?icon('video'):diagram(v.type)}</a><div class="video-copy"><h3><a href="#/v/${v.id}" title="${escapeHTML(v.title)}">${escapeHTML(v.title)}</a></h3><p>${escapeHTML(v.description)}</p><div class="video-meta">${v.tags.map(t=>`<span class="tag">${t}</span>`).join('')}<span>${v.source} · ${v.duration}</span></div></div><div>${stateDisplay(v)}</div>${v.status==='processing'||v.status==='failed'?btn(v.status==='processing'?'查看进度':'恢复处理','activity','small',`data-id="${v.id}"`):`<a class="btn small" href="#/v/${v.id}">阅读 ${icon('arrow')}</a>`}</article>`).join('')}</div>`:`<div class="empty"><h2>${q||tag||status!=='all'?'没有匹配的视频':'你的第一份摘要，从这里开始'}</h2><p>${q||tag||status!=='all'?'筛选条件已保留，换一个条件就能继续查找。':'导入一段视频，留下可阅读、可回查的内容。'}</p>${q||tag||status!=='all'?btn('清空筛选','clear-filter'):btn('导入第一个视频','import','primary',readOnly()?'disabled':'')}</div>`}${scenarioControl()}</div>`;
}
function readerStatus(){return videoScenario()==='imported'?'视频已导入 · 尚未生成摘要':videoScenario()==='failed'?'摘要未生成':videoScenario()==='multiple_errors'?'摘要可读 · 2 项未完成':videoScenario()==='processing'?state.generation==='text_ready'?'文字可读 · 正在补充画面':state.generation==='complete'?'摘要已就绪':'正在整理字幕内容':videoScenario()==='partial'?'文字可读 · 配图未完成':state.scenario==='offline'?'连接中断 · 正在恢复状态':state.scenario==='source_error'?'摘要可读 · 来源暂不可回查':legacy()?'历史摘要 · 部分来源未标注时间':readOnly()?'只读 · 当前内容可阅读':'摘要已就绪';}
function readerHTML(){const v=dataVideo(),ch=getChapters();return `<div class="reader"><header class="reader-head"><div class="reader-title"><h1>${escapeHTML(v.title)}</h1><div class="actions">${btn(icon('play')+'回放','pane-playback','ghost')}${btn(icon('ask')+'提问','pane-ask','ghost')}${btn(icon('edit')+'修改','revision','ghost',readOnly()?'disabled title="只读账号不能修改摘要"':'')}<button class="icon-button" data-action="more" aria-label="更多视频操作">${icon('more')}</button></div></div><div class="reader-meta"><span>${videoScenario()==='imported'||videoScenario()==='processing'&&['waiting','working'].includes(state.generation)?'文字来源待确认':v.source==='B 站'?'平台字幕':'语音转写'} · ${v.duration}</span>${videoScenario()==='processing'&&['waiting','working'].includes(state.generation)||videoScenario()==='imported'||videoScenario()==='failed'?'<span>尚无摘要版本</span>':`<span>当前版本 v${currentVersion()}</span>`}<button data-action="source">来源信息</button>${readOnly()?'<span class="readonly">只读账号</span>':''}</div><div class="reader-tabs" role="tablist" aria-label="内容视图"><button role="tab" data-action="read-view" data-view="summary" aria-selected="${state.view==='summary'}">摘要</button><button role="tab" data-action="read-view" data-view="map" aria-selected="${state.view==='map'}">导图</button><button class="compact-only" data-action="toc">章节</button><span class="statusline ${state.scenario==='offline'?'offline':''}"><span class="status-dot"></span>${readerStatus()}<button data-action="activity" aria-label="查看摘要处理详情">详情</button></span></div></header><div class="reader-layout ${state.side?'':'side-closed'}"><nav class="toc" aria-label="摘要章节"><span class="eyebrow">内容目录</span>${ch.map((c,i)=>`<button data-action="chapter" data-id="${c.id}" class="${i===0?'active':''}">${String(i+1).padStart(2,'0')} ${escapeHTML(c.title)}<small>${legacy()?'未标注时间':fmt(c.time)}</small></button>`).join('')}<button data-action="focus">${icon('note')} 专注阅读</button></nav><div class="document" data-version="${currentVersion()}" tabindex="0" role="region" aria-label="摘要正文">${videoScenario()==='imported'?`<div class="paper"><div class="empty"><h2>视频已保存</h2><p>你选择了仅导入。可以准备好关注点后再生成摘要。</p>${btn('开始生成摘要','retry','primary')}</div>${scenarioControl()}</div>`:videoScenario()==='failed'?`<div class="paper"><div class="empty"><h2>摘要暂未生成</h2><p>视频已经保存。本次摘要请求失败，重试会复用现有文字来源。</p>${btn('只重试摘要','retry','primary',readOnly()?'disabled':'')}</div>${scenarioControl()}</div>`:videoScenario()==='processing'&&['waiting','working'].includes(state.generation)?`<div class="paper"><span class="lead-label">已加入视频</span><h2 style="margin-top:18px">正在整理内容</h2><p class="muted">任务已受理，可以离开。完整文字发布后，阅读入口会在这里出现。</p>${btn('查看已发生的活动','activity')}<div style="height:100px"></div>${scenarioControl()}</div>`:state.view==='map'?mapHTML(ch):documentHTML(ch)}</div><aside class="assistant" aria-label="回放与提问" ${state.side?'':'hidden'}></aside></div></div>`;}
function documentHTML(ch){return `<article class="paper"><span class="lead-label">概览</span><p class="overview">${escapeHTML(summaryText())}</p><div class="tags">${(state.scenario==='long'?videoTags().concat(['业务流程','人工智能','系统设计','知识管理','工具调用','工程实践','评测','质量','方法','案例']):videoTags()).slice(0,3).map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}${videoTags().length>3||state.scenario==='long'?`<button data-action="all-tags">+ ${state.scenario==='long'?12:Math.max(0,videoTags().length-3)}</button>`:''}<button data-action="tags" ${readOnly()?'disabled':''}>管理</button></div><div class="map-preview" aria-label="摘要结构预览">${ch.slice(0,3).map(c=>`<button data-action="chapter" data-id="${c.id}"><b>${escapeHTML(c.title)}</b><span>进入章节 →</span></button>`).join('')}</div>${legacy()?'<div class="notice">历史摘要可以阅读和修订；没有真实时间的段落不提供定位按钮。</div>':''}${ch.map((c,i)=>`<section class="chapter" id="chapter-${c.id}" data-block="${c.id}"><div class="chapter-head"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><h2>${escapeHTML(c.title)}</h2></div>${!legacy()?`<button class="source-time" data-action="replay" data-time="${c.time}" data-id="${c.id}">${icon('play')}${fmt(c.time)} 回查原片</button>`:''}<p class="selectable">${escapeHTML(c.body)}</p><p>${escapeHTML(c.extra)}</p>${state.scenario==='long'?Array.from({length:5},()=>`<p>${escapeHTML(c.extra)}真实长内容需要维持段落节奏与来源定位，不能因为页面变长而丢掉阅读位置。</p>`).join(''):''}${c.figure&&!legacy()?`<figure class="figure"><button class="figure-art" data-action="image" aria-label="放大架构示意图">${diagram(dataVideo().type)}</button><figcaption><span>图 1 · 知识组织与反馈关系<br><small>本地示意图，非真实视频截图</small></span><button class="source-time" data-action="replay" data-time="${c.time+38}" data-id="${c.id}">${fmt(c.time+38)}</button></figcaption></figure>`:''}<div class="chapter-tools"><button data-action="quote" data-id="${c.id}">${icon('ask')} 选段提问</button><button data-action="revision" data-id="${c.id}" ${readOnly()?'disabled':''}>修改这一段</button></div></section>`).join('')}<footer class="article-footer"><span>${state.edited?'你已应用的修订':'生成原稿'} · v${currentVersion()}</span>${state.undoAvailable?btn('撤销上次修改','undo','small'):btn('导出 Markdown','export','small ghost')}</footer>${scenarioControl()}</article>`;}
function mapHTML(ch){return `<div class="map-view"><span class="eyebrow">同一份摘要 · v${currentVersion()}</span><h2 style="margin-top:12px">内容结构</h2><p class="map-note">点击节点回到正文。这张图只展示已保存的章节结构，不补造未生成的概念。</p><div class="map-tree"><div class="map-root">${escapeHTML(dataVideo().title)}</div>${ch.map(c=>`<div class="branch"><button data-action="chapter" data-id="${c.id}">${escapeHTML(c.title)} ${icon('arrow')}</button><p>${escapeHTML(c.body.slice(0,60))}…</p></div>`).join('')}</div>${btn('回到摘要','read-view','', 'data-view="summary"')}${scenarioControl()}</div>`;}
function fmt(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function videoTags(){return currentID==='agent'?state.tagNames:dataVideo().tags;}
function closeSide(){state.side=false;const u=route();u.searchParams.delete('pane');history.replaceState(null,'','#'+u.pathname+u.search);renderAssistant();save();}
function questionKey(){return currentRoute==='chat'?`scope:${state.scope}:${state.currentSession}`:`video:${currentID}`;}
function referenceHTML(k){const r=state.refs[k];if(!r)return '';const stale=r.version!==currentVersion();return `<div class="quote ${stale?'stale':''}"><b>摘要选段 · v${r.version}</b><p>${escapeHTML(r.quote)}</p>${stale?'<small>版本已变化，保存的选段仍保留</small><br>':''}<button data-action="return-quote">${stale?'查看保存快照':'返回原段'}</button><button data-action="remove-quote">移除</button></div>`;}
function messagesHTML(k){const m=state.messages[k]||[];if(!m.length)return `<div class="chat-empty"><h3>${currentRoute==='chat'?'从一个问题开始':'问这段内容'}</h3><p>${currentRoute==='chat'?'从选定范围中的可用视频查找依据。':'选一段摘要，或者直接输入你的问题。'}<br>回答不会修改摘要。</p><button data-action="suggest" data-text="这段内容的适用条件是什么？">这段内容的适用条件是什么？</button>${currentRoute==='chat'?'<button data-action="suggest" data-text="不同视频对反馈机制有哪些共同观点？">不同视频对反馈机制有哪些共同观点？</button>':''}</div>`;return m.map(x=>`<div class="message ${x.role==='user'?'user-message':''}">${x.role==='assistant'?'<span class="message-label">映知 · 示例回答</span>':''}${escapeHTML(x.text)}${x.ref?`<div class="quote"><b>已保存的摘要选段 · v${x.ref.version}</b><p>${escapeHTML(x.ref.quote)}</p></div>`:''}${x.role==='assistant'&&x.text?'<div class="small" style="margin-top:10px">本地规则回答，不是模型生成</div>':''}</div>`).join('');}
function composerHTML(k){return `<form class="composer" aria-label="问题输入">${referenceHTML(k)}<div class="composer-box"><textarea aria-label="输入问题" placeholder="${currentRoute==='chat'?'向这个范围提问…':'问这段视频…'}" ${readOnly()?'disabled':''}>${escapeHTML(state.drafts[k]||'')}</textarea><div class="composer-foot"><span>${activeQuestionKey===k?'正在播放本地回答事件':'普通提问 · 不修改摘要'}</span>${activeQuestionKey===k?btn('停止','stop','small'):btn('发送 '+icon('arrow'),'send','primary small',readOnly()?'disabled title="只读账号不能发送"':'')}</div></div><p class="composer-hint">${readOnly()?'只读账号可查看已有会话。':'Enter 换行 · Ctrl / ⌘ + Enter 发送'}</p></form>`;}
function renderAssistant(){const a=$('.assistant');if(!a)return;const wasInside=a.contains(document.activeElement),focusAction=document.activeElement?.dataset?.action;const k=questionKey();a.hidden=!state.side;a.innerHTML=`<header class="assistant-head"><div class="seg" role="tablist" aria-label="辅助视图"><button role="tab" data-action="pane-playback" aria-selected="${state.pane==='playback'}">回放</button><button role="tab" data-action="pane-ask" aria-selected="${state.pane==='ask'}">提问</button></div><button class="icon-button return-reader" data-action="close-side" aria-label="关闭辅助面板"><span class="compact-return">返回阅读</span>${icon('close')}</button></header>${state.pane==='playback'?`<div class="assistant-body">${state.scenario==='source_error'?'<div class="notice error">来源暂不可播放。摘要保留，可以继续阅读。</div>':`<div class="video-player"><div class="video-frame">${diagram(dataVideo().type)}<small>模拟播放器 · 本地示意图</small></div><div class="player-controls"><div class="row"><button data-action="play" aria-label="${state.playing?'暂停':'播放'}模拟视频">${state.playing?'Ⅱ':'▶'}</button><input type="range" min="0" max="904" value="${state.time}" aria-label="模拟播放时间"><span class="time" id="time-label">${fmt(state.time)}</span></div><p class="helper" style="font-size:10px;margin-top:6px">没有真实视频流，仅验证时间与定位交互</p></div></div>`}<div class="current-source"><span class="eyebrow">当前核查片段</span><h3 style="margin-top:10px" id="source-title">${escapeHTML(getChapters().filter(c=>c.time<=state.time+30).at(-1)?.title||getChapters()[0].title)}</h3><p>从摘要中的时间入口回到画面，核查具体前提、参数与表达。</p></div><div class="source-line">${legacy()?'历史摘要部分段落没有定位时间':'摘要和回放使用同一来源版本'}<br><button data-action="source">查看来源信息 →</button></div></div>`:`<div class="ask-pane"><div class="conversation">${messagesHTML(k)}</div>${activeQuestionKey===k?'<div class="chat-activity running" style="padding-left:16px"><span class="status-dot"></span> 正在组织示例回答</div>':''}${composerHTML(k)}</div>`}`;$('.reader-layout').classList.toggle('side-closed',!state.side);attachAssistantInputs();if(wasInside){if(a.hidden)document.querySelector('[data-action="pane-'+(state.pane==='ask'?'ask':'playback')+'"]')?.focus();else (a.querySelector('[data-action="'+focusAction+'"]')||a.querySelector('textarea')||a.querySelector('button'))?.focus();}}
function setPane(p){captureRead();state.pane=p;state.side=true;const u=route();u.searchParams.set('pane',p);history.replaceState(null,'','#'+u.pathname+u.search);renderAssistant();save();}
function chatHTML(){return `<div class="wide-chat"><aside class="sessions" aria-label="会话列表"><h2>问答</h2>${btn(icon('plus')+'新建问答','new-chat')}<span class="eyebrow" style="padding:0 8px">最近会话</span><button class="session" data-action="open-session" data-scope="library" data-session="feedback" aria-current="${state.currentSession==='feedback'}">不同视频中的反馈机制<small>视频库 · 示例会话</small></button><button class="session" data-action="open-session" data-scope="kb" data-session="architecture" aria-current="${state.currentSession==='architecture'}">架构约束与适用条件<small>知识库 · 示例会话</small></button><a class="session" href="#/v/agent?pane=ask">客服 Agent 的边界<small>单视频 · 回到阅读上下文</small></a><p class="helper" style="padding:20px 8px">会话的范围在创建时明确。<br>更换范围会新建会话。</p></aside><section class="cross-conversation"><header class="cross-head"><h1>${state.currentSession==='new'?'新问答':state.currentSession==='feedback'?'不同视频中的反馈机制':'架构约束与适用条件'}</h1><p><span class="scope">${state.scope==='library'?'视频库 · 已索引范围':'知识库 · Agent 架构'}</span>模拟范围；正式接入按当前模型与成员就绪检查</p></header><div class="conversation">${messagesHTML(questionKey())}</div>${composerHTML(questionKey())}</section></div>`;}
function kbHTML(id){if(!id)return `<div class="page"><div class="page-head"><div><h1>知识库</h1><p>把相关视频组织成固定的提问范围。标签不会自动改变成员。</p></div>${btn('新建知识库','new-kb', 'primary',readOnly()?'disabled':'')}</div><div class="kb-row"><div class="kb-icon">${icon('folder')}</div><div class="kb-copy"><h2><a href="#/kb/agent">Agent 架构</a></h2><p>知识组织、工具边界与反馈机制。</p><span class="small">3 个成员 · 3 个可检索 · 模拟数据</span></div><a class="btn" href="#/kb/agent">查看成员 ${icon('arrow')}</a></div><div class="kb-row"><div class="kb-icon">${icon('folder')}</div><div class="kb-copy"><h2><a href="#/kb/database">数据库实践</a></h2><p>从工作负载理解参数，而不是记住默认值。</p><span class="small">2 个成员 · 1 个需处理 · 模拟数据</span></div><a class="btn" href="#/kb/database">查看成员 ${icon('arrow')}</a></div>${scenarioControl()}</div>`;
 return `<div class="page"><a class="small" href="#/kb">← 返回知识库</a><div class="page-head" style="margin-top:22px"><div><h1>${id==='database'?'数据库实践':'Agent 架构'}</h1><p>固定成员范围 · 模拟数据 · ${id==='database'?'1 个成员未就绪':'所有成员可用于检索'}</p></div>${btn('在此知识库提问','kb-ask','primary',id==='database'?'disabled title="所有成员可检索后才能问整库"':'')}</div>${id==='database'?'<div class="notice warning">有 1 个成员在当前模型下尚不可检索。现有规则要求所有成员就绪后才能整库提问。<br><a class="btn small" href="#/v/failed">处理这份视频</a></div>':''}${videos.slice(0,id==='database'?2:3).map((v,i)=>`<div class="member-row">${icon('video')}<a href="#/v/${v.id}">${escapeHTML(v.title)}</a><span class="state ${id==='database'&&i===1?'bad':'good'}">${id==='database'&&i===1?'需建立检索索引':'可检索'}</span></div>`).join('')}<div style="margin-top:24px" class="row">${btn('管理成员','members','',readOnly()?'disabled':'')}${btn('检索诊断','diagnostic','ghost')}</div></div>`;}
function notesHTML(id){if(!id)return `<div class="page"><div class="page-head"><div><h1>学习笔记</h1><p>独立整理的笔记与历史版本，和视频摘要分别保存。</p></div>${btn('生成学习笔记','note-create','',readOnly()?'disabled':'')}</div><div class="note-row"><div class="kb-icon">${icon('note')}</div><div class="kb-copy"><h2><a href="#/notes/architecture">Agent 架构学习笔记</a></h2><p>整理概念、例子与依赖关系。保留独立版本及来源证据。</p><span class="small">学习笔记 · 独立版本 v3 · 本地模拟</span></div><a class="btn" href="#/notes/architecture">打开笔记 ${icon('arrow')}</a></div><div class="notice" style="margin-top:24px">历史入口保留。摘要的修订不会自动覆盖这里的笔记；笔记修改也不会改写视频摘要。</div></div>`;
 return `<div class="page"><a class="small" href="#/notes">← 返回学习笔记</a><div class="page-head" style="margin-top:24px"><div><h1>Agent 架构学习笔记</h1><p>独立版本 v3 · manifest 证据模型 · 模拟数据</p></div>${btn('查看笔记证据','note-evidence')}</div><div class="seg" aria-label="笔记视图">${[['text','笔记'],['map','导图'],['canvas','知识画布']].map(([v,t])=>`<button data-action="note-view" data-view="${v}" aria-pressed="${state.noteView===v}">${t}</button>`).join('')}</div>${state.noteView==='text'?'<article class="note-paper"><h2>知识组织与执行能力</h2><p>技能说明承载判断与业务知识，工具承担执行。两者通过可解释的关系连接，而不是简单堆叠功能。</p><h2>为什么保留独立学习笔记</h2><p>笔记可以整理概念、例子和个人理解，也可以建立显式依赖关系。这些内容有自己的版本与证据，不能和摘要正文混为同一份数据。</p><a class="source-time" href="#/v/agent">回到来源视频 →</a></article>':'<div class="relation-grid" aria-label="笔记关系示意"><span>业务知识</span><i>组织为 →</i><span>技能</span><i>依赖 →</i><span>工具边界</span><i>需要 →</i><span>验证与反馈</span></div><p class="helper">本原型只展示笔记关系布局。正式版本已有知识画布编辑与版本保存，此处没有模拟完整编辑器。</p>'}</div>`;}
function openDialog(kind,title,body,foot=''){dialogKind=kind;if(!$('#modal').open)lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-foot').innerHTML=foot;$('#modal').classList.toggle('activity-dialog',kind==='activity');hydrateIcons($('#modal'));if(!$('#modal').open)$('#modal').showModal();attachDialogInputs();const field=$('#modal-body input:not([type=checkbox]),#modal-body textarea');(field||$('#modal .icon-button')).focus();}
function closeDialog(){if(dialogKind==='import')saveImport();$('#modal').close();lastFocus?.focus?.();dialogKind='';save();}
function importHTML(){const d=state.importDraft;return `<div class="seg" role="tablist" aria-label="导入来源"><button role="tab" data-action="import-tab" data-tab="url" aria-selected="${d.tab==='url'}">视频链接</button><button role="tab" data-action="import-tab" data-tab="file" aria-selected="${d.tab==='file'}">本地文件</button></div>${d.tab==='url'?`<label class="field" for="import-url">B 站视频链接</label><input id="import-url" placeholder="https://www.bilibili.com/video/… 或 b23.tv/…" value="${escapeHTML(d.url)}"><p class="helper">默认导入第 1 P；链接带 p 参数时按该分 P 提交。真实来源由服务端核对。</p>`:`<label class="file-drop" for="import-file">${icon('upload')}<b>选择一个本地视频</b><small>先选择，再确认导入选项 · 2 GB 以内</small></label><input type="file" id="import-file" accept="video/*" style="position:absolute;width:1px;height:1px;opacity:0"><div id="file-name" class="file-selected">${escapeHTML(d.filename||'尚未选择文件')}</div><p class="helper">本地视频使用语音转写。正式上传合并完成前需保持页面打开。</p>`}<div id="import-error" class="field-error" role="alert"></div><label class="field" for="import-focus">关注点 <span class="small">可选</span></label><textarea id="import-focus" placeholder="例如：关注具体方法、适用条件和例子">${escapeHTML(d.focus)}</textarea><div class="options"><label class="check-label"><input id="import-visual" type="checkbox" ${d.visual?'checked':''} ${!d.auto?'disabled':''}>按需补充画面</label><label class="check-label"><input id="import-tags" type="checkbox" ${d.tags?'checked':''} ${!d.auto?'disabled':''}>自动添加标签</label></div><details class="advanced"><summary>文字来源</summary>${d.tab==='url'?'<div class="advanced-grid"><label>来源策略<select id="import-policy" aria-label="文字来源策略"><option>优先平台字幕，不可用时转写</option><option>直接语音转写</option></select></label><label>字幕语言<select id="import-language" aria-label="字幕语言"><option>自动选择</option><option>中文</option><option>英语</option></select></label></div>':'<p class="helper">本地文件使用语音转写；字幕语言偏好不适用于本地文件。</p>'}</details><details class="advanced"><summary>表达与生成</summary><div class="advanced-grid"><label>摘要形式<select id="import-form" aria-label="摘要形式" ${!d.auto?'disabled':''}><option>自动选择</option><option>文字</option><option ${!d.visual?'disabled':''}>图文</option><option ${!d.visual?'disabled':''}>关键帧</option></select></label><label>生成意图<select id="import-auto" aria-label="生成意图"><option value="yes" ${d.auto?'selected':''}>导入并生成摘要</option><option value="no" ${!d.auto?'selected':''}>仅导入视频</option></select></label></div><p class="helper">导图读取同一份摘要结构。画面与标签失败不妨碍文字阅读。</p></details>${state.scenario==='no_config'?'<div class="notice warning" style="margin-top:16px">模拟：画面能力未配置。可以生成文字摘要，配置后再补图。<br><button class="btn small" data-action="settings">查看配置</button></div>':''}<p class="helper">设计原型：不上传文件、不下载视频、不调用模型。已填写内容关闭后保留在本机。</p>`;}
function openImport(){if(readOnly())return notify('只读账号不能导入');openDialog('import','导入视频',importHTML(),'<span class="small">链接受理后可离开；本地上传完成前需留页。</span>'+btn('关闭，保留草稿','close-dialog')+btn(state.importDraft.auto?'导入并生成摘要':'仅导入视频','submit-import','primary'));}
function saveImport(){const d=state.importDraft;d.url=$('#import-url')?.value??d.url;d.focus=$('#import-focus')?.value??d.focus;d.visual=$('#import-visual')?.checked??d.visual;d.tags=$('#import-tags')?.checked??d.tags;d.policy=$('#import-policy')?.value??d.policy;d.language=$('#import-language')?.value??d.language;d.form=$('#import-form')?.value??d.form;d.auto=$('#import-auto')?$('#import-auto').value==='yes':d.auto;save();}
function activityHTML(){return `<p class="helper" style="margin-top:0">本地模拟事件。列表只显示已经开始的动作；没有总量，因此不显示百分比。</p><div class="progress-row"><h3>${escapeHTML(state.importTitle||videos[0].title)}</h3><span class="state ${state.scenario==='partial'?'working':'good'}">${readerStatus()}</span><ol class="activity-list">${state.events.map(e=>`<li class="${e.state}"><span>${e.state==='done'?'✓':e.state==='error'?'!':'·'}</span><span>${escapeHTML(e.title)}${e.state==='error'?'<small>文字摘要保留；查看详情确认相关恢复动作。</small>':''}</span><time>${escapeHTML(e.duration)}</time></li>`).join('')}</ol><div class="row wrap" style="margin-top:12px"><a class="btn small" href="#/v/${state.importTitle?'imported':'agent'}" data-action="dialog-link">${state.generation==='waiting'?'打开视频':'阅读摘要'}</a>${state.scenario==='partial'?btn('只重试配图','retry-visual','small',readOnly()?'disabled':''):state.scenario==='processing'?btn('下一模拟事件','advance','small'):''}${state.scenario==='offline'?btn('模拟重连','reconnect','small'):''}</div></div><div class="progress-row"><h3>消息队列的重复投递与幂等处理</h3><span class="state working"><span class="status-dot"></span>等待开始</span><p>受理已保存，尚无新的活动。</p></div><p class="helper">正式动态入口需汇总视频处理、摘要 generation 和笔记 run；现有 tasks 接口不能代替全部摘要状态。</p>`;}
function openActivity(){openDialog('activity','处理动态',activityHTML(),btn('关闭','close-dialog'));}
function openRevision(block){if(readOnly())return;if(currentID!=='agent'||block&&block!=='pain'){openDialog('revision-boundary','修改演示范围','<p class="helper">本地固定差异只覆盖第一个视频的第一段。其他段落保留设计入口，不模拟没有准备好的修改内容。</p>',btn('返回阅读','close-dialog'));return;}const c=block?getChapters().find(x=>x.id===block):getChapters()[0];state.revision=state.revision||{base:state.version,block:c.id,instruction:'',stage:'draft'};if(block&&state.revision.stage==='draft')state.revision.block=block;revisionDialog();save();}
function revisionDialog(){const r=state.revision,c=getChapters().find(x=>x.id===r.block)||getChapters()[0];let body=`<div class="version-flag"><span>基于摘要 v${r.base}</span><span>${r.stage==='ready'?'预览就绪 · 未应用':r.stage==='running'?'正在准备预览':'只修改所选段落'}</span></div><h3>${escapeHTML(c.title)}</h3>`;if(r.stage==='draft')body+=`<label class="field" for="revision-instruction">你希望怎样修改？</label><textarea id="revision-instruction" placeholder="例如：更简洁，保留具体问题与条件">${escapeHTML(r.instruction)}</textarea><p class="helper">修改会先形成预览。普通提问不会进入这个流程。</p>`;else if(r.stage==='running')body+='<p class="helper">正在重放本地修订活动：整理措辞。</p>';else body+=`<div class="diff"><span class="small">修改前 · v${r.base}</span>${escapeHTML(agentChapters[0].body)}</div><div class="diff after"><span class="small">修改后 · 尚未应用</span>传统客服系统的维护难点是业务知识分散：同一个场景要在意图、话术和流程等配置之间来回切换。新人需要先理解这些关系，才能做出可靠调整。</div><p class="helper">此处为固定演示差异，未调用模型。应用后保留历史引用，但旧版本引用不定位到新正文。</p>${r.base!==state.version?'<div class="notice error">当前摘要已变化，不能把这个预览直接应用到新版本。</div>':''}`;openDialog('revision','预览摘要修改',body,btn('关闭，保留预览','close-dialog')+(r.stage==='draft'?btn('生成修改预览','preview','primary'):r.stage==='ready'?btn(`应用到 v${r.base}，生成 v${r.base+1}`,'apply','primary',r.base!==state.version?'disabled':''):btn('正在准备…','noop','primary','disabled')));}
function openSettings(tab='ai'){openDialog('settings','设置',`<div class="seg settings-tabs">${[['ai','AI 服务'],['appearance','外观'],['memory','记忆'],['prompt','提示词']].map(([v,n])=>`<button data-action="settings-tab" data-tab="${v}" aria-pressed="${tab===v}">${n}</button>`).join('')}</div>${tab==='ai'?`<h3>服务可用性</h3><p class="helper">这是模拟配置状态，不能在这里保存真实 API 密钥。</p>${[['摘要与问答','可用'],['语音识别','可用'],['画面理解',state.scenario==='no_config'?'未配置':'可用'],['跨视频检索','示例范围已就绪']].map(([n,s])=>`<div class="settings-row"><span>${n}</span><span class="state ${s==='未配置'?'bad':'good'}">${s}</span></div>`).join('')}<p class="helper">正式配置修改只影响之后的新请求。在途请求使用冻结配置；回到任务后由用户明确继续。</p>`:tab==='appearance'?`<h3>外观</h3><div class="row">${btn('切换深色 / 浅色','theme')}</div><p class="helper">同一结构与字号，不用主题切换制造新的布局。</p>`:tab==='memory'?'<h3>记忆治理</h3><p class="helper">现有记忆偏好、捕获状态和删除能力保留在该分区。本原型不读取、写入或删除真实记忆。</p>':'<h3>提示词偏好</h3><p class="helper">现有按功能配置保留。保存草稿与离开保护需要沿用，不在原型模拟业务保存。</p>'}`,btn('返回原页面','close-dialog'));}
function attachInputs(){const search=$('input[aria-label="搜索视频"]');if(search)search.addEventListener('input',()=>{clearTimeout(search._timer);search._timer=setTimeout(()=>{const pos=search.selectionStart;const u=route();u.searchParams.set('q',search.value);history.replaceState(null,'','#'+u.pathname+u.search);render();const n=$('input[aria-label="搜索视频"]');n.focus();n.setSelectionRange(pos,pos);},200);});const sc=$('select[aria-label="选择模拟场景"]');if(sc)sc.addEventListener('change',()=>{state.scenario=sc.value;state.playing=false;if(sc.value==='processing'){state.generation='waiting';state.events=[{title:'导入任务已受理',state:'done',duration:'刚刚'}];}if(sc.value==='partial')state.events=[{title:'发布文字摘要',state:'done',duration:'18 秒'},{title:'查看相关画面',state:'error',duration:'失败'}];if(sc.value==='multiple_errors')state.events=[{title:'发布文字摘要',state:'done',duration:'18 秒'},{title:'查看相关画面',state:'error',duration:'失败'},{title:'自动分类标签',state:'error',duration:'失败'}];if(sc.value==='readonly')state.side=false;render();});attachAssistantInputs();}
function attachAssistantInputs(){const t=$('textarea[aria-label="输入问题"]');if(t){t.addEventListener('input',()=>{state.drafts[questionKey()]=t.value;save();});t.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();sendQuestion();}});}const range=$('input[aria-label="模拟播放时间"]');if(range)range.addEventListener('input',()=>{state.time=Number(range.value);$('#time-label').textContent=fmt(state.time);save();});document.querySelectorAll('form.composer').forEach(f=>f.addEventListener('submit',e=>e.preventDefault()));}
function attachDialogInputs(){if(dialogKind==='import'){for(const [id,key] of [['import-policy','policy'],['import-language','language'],['import-form','form']]){const el=$('#'+id);if(el){el.value=state.importDraft[key]||el.options[0].value;el.addEventListener('change',saveImport);}}['import-url','import-focus','import-tags'].forEach(id=>{const el=$('#'+id);if(el)el.addEventListener('input',saveImport);});$('#import-file')?.addEventListener('change',e=>{const f=e.target.files[0];if(f){state.importDraft.filename=f.name;state.importDraft.fileSize=f.size;$('#file-name').textContent=f.name;save();}});$('#import-visual')?.addEventListener('change',()=>{saveImport();const f=$('#import-form');f.value=state.importDraft.visual?'自动选择':'文字';[...f.options].forEach(o=>{if(['图文','关键帧'].includes(o.text))o.disabled=!state.importDraft.visual;});saveImport();});$('#import-auto')?.addEventListener('change',()=>{saveImport();const a=state.importDraft.auto;$('#import-tags').disabled=!a;$('#import-visual').disabled=!a;$('#import-form').disabled=!a;$('#modal-foot [data-action="submit-import"]').textContent=a?'导入并生成摘要':'仅导入视频';});}$('#revision-instruction')?.addEventListener('input',e=>{state.revision.instruction=e.target.value;save();});}
function setFilter(key,value){const u=route();if(value)u.searchParams.set(key,value);else u.searchParams.delete(key);routeTo(u.pathname+u.search);}
function sendQuestion(){if(readOnly())return;const k=questionKey(),text=(state.drafts[k]||'').trim();if(!text)return notify('先输入一个问题');if(activeQuestionKey)return notify('当前示例回答尚未停止');const ref=state.refs[k];if(ref&&ref.version!==currentVersion())return notify('选段版本已变化，请移除旧引用并重新选择；问题草稿已保留');state.messages[k]=state.messages[k]||[];state.messages[k].push({role:'user',text,ref:ref?{...ref}:null},{role:'assistant',text:''});state.drafts[k]='';state.refs[k]=null;activeQuestionKey=k;const answer= currentRoute==='chat'?'在这个模拟范围中，反馈机制的共同目标是把错误案例变成可以验证的改进：先收集案例，再明确判断依据，最后通过评测检查更新效果。正式回答应列出真实命中来源；本演示没有做检索。':ref?'你选中的段落强调了业务知识分散这一问题。可以先把同一场景中的判断依据和操作整理在一起，再检查是否遗漏权限、失败和用户确认条件。这个示例回答不会改动摘要。':'这里的关键是把技能说明和执行工具分开：前者组织业务知识，后者提供受约束的操作能力。具体适用性仍需回到真实视频核查；本回答是本地模拟。';let i=0;const slot=state.messages[k].at(-1);save();refreshQuestionUI();answerTimer=setInterval(()=>{i=Math.min(answer.length,i+4);slot.text=answer.slice(0,i);const visible=questionKey()===k&&(currentRoute==='chat'||currentRoute==='video'&&state.pane==='ask');if(visible){const conv=$('.conversation');if(conv){const near=conv.scrollHeight-conv.scrollTop-conv.clientHeight<80;const last=conv.querySelector('.message:last-child');if(last)last.innerHTML='<span class="message-label">映知 · 示例回答</span>'+escapeHTML(slot.text);if(near)conv.scrollTop=conv.scrollHeight;}}if(i===answer.length){clearInterval(answerTimer);activeQuestionKey=null;save();refreshQuestionUI();}},45);}
function refreshQuestionUI(){if(currentRoute==='video')renderAssistant();else if(currentRoute==='chat'){const pos=$('.conversation')?.scrollTop||0;$('#main').innerHTML=chatHTML();hydrateIcons($('#main'));attachAssistantInputs();$('.conversation').scrollTop=pos;}}
function advance(){if(state.generation==='waiting'){state.generation='working';state.events.push({title:'整理字幕内容',state:'running',duration:'进行中'});}else if(state.generation==='working'){state.generation='text_ready';state.events.at(-1).state='done';state.events.at(-1).duration='18 秒';state.events.push({title:'发布文字摘要',state:'done',duration:'刚刚'},{title:'查看相关画面',state:'running',duration:'进行中'});}else{state.generation='complete';state.events.at(-1).state='done';state.events.at(-1).duration='9 秒';state.events.push({title:'保存本地示例结果',state:'done',duration:'刚刚'});}syncImported();save();if($('#modal').open&&dialogKind==='activity')openActivity();else render();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,k=questionKey();
 switch(a){
 case 'skip-main':e.preventDefault();$('#main').focus();break;
 case 'theme':state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;$('#theme-label').textContent=state.theme==='dark'?'浅色外观':'深色外观';save();break;
 case 'import':openImport();break;
 case 'import-tab':saveImport();state.importDraft.tab=el.dataset.tab;openImport();break;
 case 'submit-import':{saveImport();const d=state.importDraft;let error='';if(d.tab==='url'){try{const u=new URL(d.url);if(u.protocol!=='https:'||!/(^|\.)bilibili\.com$/.test(u.hostname)&&u.hostname!=='b23.tv')error='请输入 HTTPS 的 B 站视频或 b23.tv 链接';else if(u.searchParams.has('p')&&!/^[1-9]\d*$/.test(u.searchParams.get('p')))error='分 P 参数应为正整数';}catch{error='请先粘贴完整的视频链接';}}else if(!d.filename)error='先选择一个视频文件';else if(d.fileSize>2*1024**3)error='文件需在 2 GB 以内';if(error){$('#import-error').textContent=error;($('#import-url')||$('#import-file')).focus();break;}state.importTitle=d.tab==='url'?'刚导入的视频 · 模拟任务':d.filename;state.scenario=d.auto?'processing':'imported';state.generation='waiting';state.events=[{title:d.tab==='file'?'本地演示上传已受理':'链接导入任务已受理',state:'done',duration:'刚刚'}];syncImported();state.side=false;closeDialog();routeTo('/v/imported');notify('模拟任务已创建。不会真正上传、下载或产生费用。');break;}
 case 'filter':setFilter('status',el.dataset.status==='all'?'':el.dataset.status);break;
 case 'filter-tag':setFilter('tag',route().searchParams.get('tag')===el.dataset.tag?'':el.dataset.tag);break;
 case 'filter-tags':openDialog('filter-tags','按标签找视频','<p class="helper">本原型为单标签筛选演示；正式方案保留现有多选 AND / OR。</p><div class="options">'+[...new Set(videos.flatMap(v=>v.tags))].map(t=>`<button class="tag-button" data-action="choose-filter-tag" data-tag="${t}">${t}</button>`).join('')+'</div>',btn('关闭','close-dialog'));break;
 case 'choose-filter-tag':closeDialog();setFilter('tag',el.dataset.tag);break;
 case 'list-view':setFilter('view',el.dataset.view);break;
 case 'clear-filter':routeTo('/library');break;
 case 'pane-playback':setPane('playback');break;
 case 'pane-ask':setPane('ask');break;
 case 'close-side':closeSide();break;
 case 'read-view':state.view=el.dataset.view;render();break;
 case 'chapter':{const id=el.dataset.id;if($('#modal').open)closeDialog();if(state.view!=='summary'){state.view='summary';render();}const c=$('#chapter-'+id);c?.scrollIntoView({block:'start'});document.querySelectorAll('.toc button').forEach(x=>x.classList.toggle('active',x.dataset.id===id));break;}
 case 'toc':openDialog('toc','摘要章节',getChapters().map(c=>btn(escapeHTML(c.title),'chapter','ghost',`data-id="${c.id}"`)).join('<br>'),btn('关闭','close-dialog'));break;
 case 'focus':closeSide();notify('已专注阅读，正文保持舒适行宽；回放和提问仍可打开。');save();break;
 case 'quote':{const c=getChapters().find(x=>x.id===el.dataset.id);state.refs[k]={block:c.id,quote:c.body,version:currentVersion()};setPane('ask');save();$('textarea[aria-label="输入问题"]')?.focus();break;}
 case 'quote-selection':if(selectedQuote){state.refs[k]=selectedQuote;setPane('ask');$('.selection-bar')?.remove();save();}break;
 case 'return-quote':{const r=state.refs[k];if(!r)break;if(r.version!==currentVersion()){openDialog('snapshot',`保存的选段 · v${r.version}`,`<p style="line-height:1.9">${escapeHTML(r.quote)}</p><p class="helper">当前是 v${currentVersion()}。不会将这个旧引用定位到新正文；可保留快照，或移除后重新选择。</p>`,btn('关闭','close-dialog'));}else{$('#chapter-'+r.block)?.scrollIntoView({block:'start'});if(innerWidth<=1100)closeSide();}break;}
 case 'remove-quote':state.refs[k]=null;refreshQuestionUI();save();break;
 case 'replay':state.time=Number(el.dataset.time);state.playing=false;setPane('playback');$('#source-title').textContent=getChapters().find(c=>c.id===el.dataset.id)?.title||'当前片段';break;
 case 'play':state.playing=!state.playing;renderAssistant();notify(state.playing?'模拟播放：时间由滑块控制，不含真实视频流。':'模拟播放已暂停');save();break;
 case 'image':openDialog('image','架构示意图 · 模拟素材',`<div style="height:320px">${diagram(dataVideo().type)}</div><p class="helper">本地 SVG 示意图，不能作为 Agent 找到了真实视频截图的证据。</p>`,btn('关闭','close-dialog'));break;
 case 'source':openDialog('source','视频与来源',`<h3>${escapeHTML(dataVideo().title)}</h3><div class="settings-row"><span>导入来源</span><span>${dataVideo().source} · 模拟</span></div><div class="settings-row"><span>文字来源</span><span>${legacy()?'历史摘要':'平台字幕 / 示例cue'}</span></div><div class="settings-row"><span>摘要版本</span><span>v${currentVersion()}</span></div><p class="helper">原文件名、分 P、文字来源身份和媒体版本应在这里查看。来源刷新与索引维护在正式产品中需要真实接口和版本核对。</p>`,btn('返回阅读','close-dialog'));break;
 case 'more':openDialog('more','视频操作',`<div style="display:grid;gap:10px">${btn('修改摘要','revision','',readOnly()?'disabled':'')}${btn('导出当前 Markdown','export')}${btn('视频与来源','source')}<a class="btn" href="#/notes/architecture" data-action="dialog-link">关联学习笔记 · 独立版本</a>${state.undoAvailable?btn('撤销上次修改','undo'):''}${btn('摘要版本边界','version-info')}${btn('专注阅读','focus')}</div>`,btn('关闭','close-dialog'));break;
 case 'version-info':openDialog('versions','当前版本与引用',`<p>当前摘要：v${currentVersion()}</p><p class="helper">本地演示保留修订前后身份，用于检查旧引用失配。正式接口已支持预览、应用、撤销与冲突处理；任意历史版本列表与读取仍需核对补齐。</p>`,btn('关闭','close-dialog'));break;
 case 'revision':openRevision(el.dataset.id);break;
 case 'preview':if(!state.revision.instruction.trim()){notify('先填写修改要求');break;}state.revision.stage='running';revisionDialog();setTimeout(()=>{if(state.revision?.stage==='running'){state.revision.stage='ready';save();if(dialogKind==='revision'&&$('#modal').open)revisionDialog();else notify('本地修改预览已就绪，尚未应用。');}},650);break;
 case 'apply':if(state.revision.base!==state.version)return notify('版本已变化，请重新预览');state.version++;state.edited=true;state.undoAvailable=true;state.revision=null;closeDialog();render();notify(`已应用为 v${currentVersion()}；旧引用与问题草稿保留。`);break;
 case 'undo':if(readOnly())return;if(!state.undoAvailable)break;state.version++;state.edited=false;state.undoAvailable=false;if($('#modal').open)closeDialog();render();notify(`已撤销，当前版本 v${currentVersion()}。文字还原，版本身份仍为新修订。`);break;
 case 'tags':if(currentID!=='agent'){openDialog('tags-fixture','标签管理示例','<p class="helper">这个视频的标签仅用于布局评审。可返回第一个视频体验本地增删；这里不模拟写入其他对象。</p>',btn('关闭','close-dialog'));break;}openDialog('tags','管理视频标签','<p class="helper">本地模拟关系，关闭后保留；正式服务保留人工优先、拒绝记录与 CAS。</p>'+state.tagNames.map((t,i)=>`<div class="settings-row"><span>${escapeHTML(t)}<small>${i<2?'人工维护':'自动标签 · 模拟'}</small></span>${btn('移除','remove-tag','small ghost',`data-tag="${escapeHTML(t)}"`)}</div>`).join('')+'<label class="field" for="new-tag">添加标签</label><div class="row"><input id="new-tag" placeholder="输入标签名称">'+btn('添加','add-tag')+'</div>',btn('完成','tags-done','primary'));break;
 case 'remove-tag':state.tagNames=state.tagNames.filter(x=>x!==el.dataset.tag);el.closest('.settings-row').remove();save();break;
 case 'add-tag':{const text=$('#new-tag').value.trim();if(text&&!state.tagNames.includes(text)){state.tagNames.push(text);save();notify('本地标签已添加');$('#new-tag').value='';}break;}
 case 'tags-done':closeDialog();render();break;
 case 'all-tags':openDialog('tags-read','此视频的标签',`<div class="options">${videoTags().map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}</div><p class="helper">长内容场景中的额外标签只是压力测试，正式关系上限以服务端为准。</p>`,btn('关闭','close-dialog'));break;
 case 'activity':openActivity();break;
 case 'advance':advance();break;
 case 'retry':state.scenario='processing';state.generation='working';state.events.push({title:'重试摘要整理 · 尝试 2',state:'running',duration:'进行中'});render();notify('已受理本地模拟重试，媒体与文字来源保留');break;
 case 'retry-visual':state.scenario='processing';state.generation='text_ready';state.events.push({title:'查看相关画面 · 尝试 2',state:'running',duration:'进行中'});openActivity();save();break;
 case 'reconnect':state.scenario='normal';openActivity();notify('已恢复本地状态快照；没有重新发送任务');save();break;
 case 'suggest':state.drafts[k]=el.dataset.text;refreshQuestionUI();save();$('textarea[aria-label="输入问题"]')?.focus();break;
 case 'send':sendQuestion();break;
 case 'stop':clearInterval(answerTimer);if(activeQuestionKey){state.messages[activeQuestionKey].at(-1).text+='（本地演示已停止）';activeQuestionKey=null;}refreshQuestionUI();save();break;
 case 'new-chat':openDialog('scope','新建问答','<p class="helper">先确定问题范围。当前标签筛选不会自动成为问答范围。</p><div style="display:grid;gap:12px;margin-top:20px">'+btn('视频库中可检索的视频','choose-scope','', 'data-scope="library"')+btn('知识库 · Agent 架构','choose-scope','', 'data-scope="kb"')+'<a class="btn" href="#/v/agent?pane=ask" data-action="dialog-link">单视频 · 在摘要中提问</a></div>',btn('取消','close-dialog'));break;
 case 'choose-scope':state.scope=el.dataset.scope;state.currentSession='new';closeDialog();render();break;
 case 'open-session':state.scope=el.dataset.scope;state.currentSession=el.dataset.session;if(!state.messages[questionKey()])state.messages[questionKey()]=[{role:'user',text:'如何理解反馈机制的适用条件？'},{role:'assistant',text:'这是保存的示例会话。反馈需要有可核查的输入和明确的评测规则，不能把反馈本身等同于质量提升。'}];render();break;
 case 'kb-ask':state.scope='kb';state.currentSession='new';routeTo('/chat');break;
 case 'settings':if(dialogKind==='import')saveImport();openSettings();break;
 case 'settings-tab':openSettings(el.dataset.tab);break;
 case 'new-kb':openDialog('new-kb','新建知识库','<label class="field" for="kb-name">名称</label><input id="kb-name" placeholder="例如：Agent 架构"><p class="helper">此原型不模拟创建与持久化成员。查看已有两个示例可评审成员与问答流程。</p>',btn('返回示例','close-dialog'));break;
 case 'members':openDialog('members','管理知识库成员',videos.slice(0,3).map(v=>`<div class="settings-row"><span>${escapeHTML(v.title)}</span><span class="state good">已加入示例集合</span></div>`).join('')+'<p class="helper">不模拟真实成员写入；正式接入保留归属与就绪检查。</p>',btn('关闭','close-dialog'));break;
 case 'diagnostic':openDialog('diagnostic','检索诊断','<p class="helper">保留现有检索测试台与运行详情的次级入口。这里没有发出检索请求；正文阅读不需要使用诊断工具。</p>',btn('返回知识库','close-dialog'));break;
 case 'note-view':state.noteView=el.dataset.view;render();break;
 case 'note-create':openDialog('note-create','生成学习笔记','<p class="helper">正式产品已有独立学习笔记生成、版本与证据模型。本原型没有发起生成；它不会把摘要复制成第二份同时维护的正文。</p><a class="btn" href="#/notes/architecture" data-action="dialog-link">查看独立笔记示例</a>',btn('关闭','close-dialog'));break;
 case 'note-evidence':openDialog('note-evidence','笔记证据 · 独立模型','<p>笔记块：知识组织与执行能力</p><p class="helper">正式读取基于 Artifact version / manifest / evidence ID；不复用 SummaryRevision 身份。本地示例没有实际证据文件。</p><a class="btn" href="#/v/agent" data-action="dialog-link">回到来源视频</a>',btn('关闭','close-dialog'));break;
 case 'export':{const text=`# ${dataVideo().title}\n\n> 设计原型 · 模拟内容 · v${currentVersion()}\n\n${summaryText()}\n\n${getChapters().map(c=>'## '+c.title+'\n\n'+c.body+'\n\n'+c.extra).join('\n\n')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='vidlens-prototype-summary-v'+state.version+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出本地模拟内容，不是服务端摘要');break;}
 case 'about':openDialog('about','设计原型与证据边界','<p style="line-height:1.9">本页面用于评审整站信息架构、阅读布局、导入、问答、修订和状态连续性。</p><p class="helper">视频、标题、摘要、标签、会话、活动、修订与播放均为本地模拟。没有真实 Agent、模型、视频流、下载、上传或后台进程。视图与草稿保存在本机独立 localStorage，不与业务账号连接。</p><p class="helper">已存在的源码能力、未接入能力和真实验收缺口详见配套方案。不会用原型中的丰富内容证明生成质量。</p><p class="helper">完整方案：docs/design/2026-10-10-summary-ui-system-v3.md（请使用聊天中的文件链接打开）。</p>',btn('关闭','close-dialog')+btn('重置本地原型','reset'));break;
 case 'reset':videos.splice(0,videos.length,...videos.filter(v=>v.id!=='imported'));clearInterval(answerTimer);activeQuestionKey=null;state=structuredClone(baseState);state.side=innerWidth>1100;closeDialog();save();routeTo('/library');render();notify('已重置本地演示，业务数据未被访问');break;
 case 'close-dialog':closeDialog();break;
 case 'dialog-link':closeDialog();break;
 }
});
document.addEventListener('mouseup',e=>{if(!e.target.closest('.selectable'))return;const selection=window.getSelection(),text=selection?.toString().trim();$('.selection-bar')?.remove();if(!text||text.length>3000)return;const section=e.target.closest('.chapter');if(!section)return;selectedQuote={block:section.dataset.block,quote:text,version:currentVersion()};const bar=document.createElement('div');bar.className='selection-bar';bar.innerHTML=btn('用选中文字提问','quote-selection','small');document.body.append(bar);});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#modal').open){const nodes=[...$('#modal').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],summary')].filter(x=>x.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'&&!$('#modal').open){$('.selection-bar')?.remove();if(currentRoute==='video'&&state.side)closeSide();}const t=e.target.closest('[role=tab]');if(t&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=[...t.parentElement.querySelectorAll('[role=tab]')],idx=tabs.indexOf(t),next=tabs[(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.focus();next.click();}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#modal').addEventListener('click',e=>{if(e.target!==$('#modal'))return;const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog();});
window.addEventListener('hashchange',()=>{if($('#modal').open)closeDialog();const u=route();if(['ask','playback'].includes(u.searchParams.get('pane'))){state.pane=u.searchParams.get('pane');state.side=true;}render();});
window.addEventListener('beforeunload',()=>{captureRead();state.playing=false;if(activeQuestionKey){state.messages[activeQuestionKey].at(-1).text+='（刷新中断本地输出，可重新提问）';save();}});
if(['ask','playback'].includes(route().searchParams.get('pane'))){state.pane=route().searchParams.get('pane');state.side=true;}
render();
